import{_ as s,c as a,d as e,o as t}from"./app-I5fDrtfX.js";const p={};function o(c,n){return t(),a("div",null,[...n[0]||(n[0]=[e(`<h1 id="go-wind-uba-拆解系列-olap-与-sql-硬核-25-个分析模型怎么落地" tabindex="-1"><a class="header-anchor" href="#go-wind-uba-拆解系列-olap-与-sql-硬核-25-个分析模型怎么落地"><span>Go Wind UBA 拆解系列 - OLAP 与 SQL 硬核：25 个分析模型怎么落地</span></a></h1><blockquote><p>本文回答一个问题：<strong>25 个分析模型（漏斗 / 留存 / LTV / 归因 / 路径……）在 ClickHouse 和 Doris 上，到底是用什么 SQL 写出来的？双引擎又是怎么做到&quot;一份业务模型，两份实现&quot;的？</strong></p></blockquote><h2 id="一、为什么是双引擎" tabindex="-1"><a class="header-anchor" href="#一、为什么是双引擎"><span>一、为什么是双引擎？</span></a></h2><p>先说结论：GoWind UBA 支持 <strong>ClickHouse 和 Apache Doris 二选一</strong>，部署时按需选其一，运行时通过一个开关切换。这是一个很有意思的工程选择——为什么不让用户自己写 SQL，而要维护两份？</p><p>因为 <strong>25 个分析模型 × 2 套方言 = 50 份 SQL</strong>，但其中只有<strong>少量函数</strong>是不同的。平台的赌注是：把&quot;相同的 SQL 骨架&quot;抽出来，只换&quot;少数分歧的函数和驱动 API&quot;，就能让同一套业务逻辑跑在两个引擎上，给用户选择权。</p><p>让我们看看这个赌注怎么兑现的。</p><h2 id="二、双引擎切换-一个编译期常量" tabindex="-1"><a class="header-anchor" href="#二、双引擎切换-一个编译期常量"><span>二、双引擎切换：一个编译期常量</span></a></h2><p>切换开关在 <code>backend/app/core/service/internal/data/data.go</code>：</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token comment">// UseClickHouse 是否使用ClickHouse作为数据存储，否则使用Doris。</span></span>
<span class="line"><span class="token keyword">const</span> UseClickHouse <span class="token builtin">bool</span> <span class="token operator">=</span> <span class="token boolean">false</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>注意：这是一个 <code>const bool</code>，不是运行期配置。</strong> 想换引擎，改这一行重编译。这是个诚实的取舍——双引擎在运行期动态切换会让代码复杂度爆炸（要同时维护两套连接池、做事务一致性等），而绝大多数生产部署只会选一个引擎。用编译期常量换来的是：另一个引擎的 client 连接都不会建立。</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token comment">// client/clickhouse_client.go</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">NewClickHouseClient</span><span class="token punctuation">(</span>ctx <span class="token operator">*</span>bootstrap<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token operator">*</span>clickhouseCrud<span class="token punctuation">.</span>Client<span class="token punctuation">,</span> <span class="token keyword">func</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token operator">!</span>data<span class="token punctuation">.</span>UseClickHouse <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> <span class="token keyword">func</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token boolean">nil</span>   <span class="token comment">// 永远不连 ClickHouse</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token comment">// ...建立连接</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// client/doris_client.go</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">NewDorisClient</span><span class="token punctuation">(</span>ctx <span class="token operator">*</span>bootstrap<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token operator">*</span>dorisCrud<span class="token punctuation">.</span>Client<span class="token punctuation">,</span> <span class="token keyword">func</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> data<span class="token punctuation">.</span>UseClickHouse <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> <span class="token keyword">func</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token boolean">nil</span>   <span class="token comment">// 永远不连 Doris</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token comment">// ...</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>两个 repo 在 Wire 里<strong>都注册</strong>，但只有被选中那个的 client 会真连。Service 层持两个 repo 指针，按常量分支：</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>s <span class="token operator">*</span>AnalyticsService<span class="token punctuation">)</span> <span class="token function">repo</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">interface</span> <span class="token punctuation">{</span> <span class="token comment">/* 24 个分析方法的接口 */</span> <span class="token punctuation">}</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> data<span class="token punctuation">.</span>UseClickHouse <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> s<span class="token punctuation">.</span>ckRepo</span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">return</span> s<span class="token punctuation">.</span>dorisRepo</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这个 <code>repo()</code> 返回一个<strong>内联接口</strong>——列出所有 24 个分析方法签名。两套 repo 都实现它，service 层无感。<code>if data.UseClickHouse</code> 这个分支模式在 10+ 个 service 文件里重复出现（<code>behavior_event_service</code> / <code>risk_event_service</code> / <code>session_service</code>……）。</p><h2 id="三、schema-同一张表-两种-ddl" tabindex="-1"><a class="header-anchor" href="#三、schema-同一张表-两种-ddl"><span>三、Schema：同一张表，两种 DDL</span></a></h2><p>最基础的事实表是 <code>events_fact</code>。在 Go 代码里，它有两份镜像定义：</p><ul><li><code>internal/data/doris/schema/events_fact.go</code> —— 用 <code>db:</code> tag</li><li><code>internal/data/clickhouse/schema/events_fact.go</code> —— 用 <code>ch:</code> tag</li></ul><p>注意作者<strong>故意没有</strong>用&quot;一个 struct + 两套 tag&quot;的统一方案，而是维护两份。原因是两个引擎对字段的语义差异不小（比如 ClickHouse 有 <code>MATERIALIZED</code> 物化列、原生 map 类型；Doris 有 <code>GENERATED ALWAYS</code> 列、自定义 Map 别名），硬塞一个 struct 反而别扭。</p><p>字段大概有 50 个：事件主体（event_id/tenant_id/user_id）、时间（event_time/event_ts/server_time）、行为（event_category/event_name）、客体（object_*）、上下文（session_id/platform/os/channel）、地图列（context/metrics/properties 都是 map）、企业字段（risk_level/trace_id）、点击热力图（click_x/click_y/element_xpath/page_url）、游戏专属（server_id/level）。</p><h3 id="_3-1-clickhouse-ddl-sql-clickhouse-1-base-tables-sql" tabindex="-1"><a class="header-anchor" href="#_3-1-clickhouse-ddl-sql-clickhouse-1-base-tables-sql"><span>3.1 ClickHouse DDL（<code>sql/clickhouse/1_base_tables.sql</code>）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code><span class="line"><span class="token keyword">CREATE</span> <span class="token keyword">TABLE</span> <span class="token keyword">IF</span> <span class="token operator">NOT</span> <span class="token keyword">EXISTS</span> gw_uba<span class="token punctuation">.</span>events_fact</span>
<span class="line"><span class="token punctuation">(</span></span>
<span class="line">    event_id       String<span class="token punctuation">,</span></span>
<span class="line">    tenant_id      UInt32  <span class="token keyword">COMMENT</span> <span class="token string">&#39;租户 ID（SaaS 多租户隔离，所有查询必须带此条件）&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    user_id        UInt32<span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span></span>
<span class="line">    event_time     DateTime64<span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    event_date     <span class="token keyword">Date</span> MATERIALIZED toDate<span class="token punctuation">(</span>event_time<span class="token punctuation">)</span><span class="token punctuation">,</span>        <span class="token comment">-- 物化列：分区+TTL 用</span></span>
<span class="line">    event_ts       Int64 MATERIALIZED toUnixTimestamp64Milli<span class="token punctuation">(</span>event_time<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span></span>
<span class="line">    event_category LowCardinality<span class="token punctuation">(</span>String<span class="token punctuation">)</span><span class="token punctuation">,</span>                       <span class="token comment">-- 低基数优化</span></span>
<span class="line">    event_name     LowCardinality<span class="token punctuation">(</span>String<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span></span>
<span class="line">    context        Map<span class="token punctuation">(</span>String<span class="token punctuation">,</span> String<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    metrics        Map<span class="token punctuation">(</span>String<span class="token punctuation">,</span> Float64<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    properties     Map<span class="token punctuation">(</span>String<span class="token punctuation">,</span> String<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token comment">-- 跳数索引（data-skipping）</span></span>
<span class="line">    <span class="token keyword">INDEX</span> idx_object_id      object_id     <span class="token keyword">TYPE</span> bloom_filter<span class="token punctuation">(</span><span class="token number">0.01</span><span class="token punctuation">)</span> GRANULARITY <span class="token number">4</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token keyword">INDEX</span> idx_context_keys   mapKeys<span class="token punctuation">(</span>context<span class="token punctuation">)</span> <span class="token keyword">TYPE</span> bloom_filter<span class="token punctuation">(</span><span class="token number">0.01</span><span class="token punctuation">)</span> GRANULARITY <span class="token number">2</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token keyword">INDEX</span> idx_element_xpath  element_xpath <span class="token keyword">TYPE</span> ngrambf_v1<span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span> GRANULARITY <span class="token number">4</span><span class="token punctuation">,</span>  <span class="token comment">-- ngram 分词，子串搜索</span></span>
<span class="line">    <span class="token keyword">INDEX</span> idx_risk           risk_level    <span class="token keyword">TYPE</span> <span class="token keyword">set</span><span class="token punctuation">(</span><span class="token number">4</span><span class="token punctuation">)</span> GRANULARITY <span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span></span>
<span class="line"><span class="token punctuation">)</span> <span class="token keyword">ENGINE</span> <span class="token operator">=</span> MergeTree</span>
<span class="line">  <span class="token keyword">PARTITION</span> <span class="token keyword">BY</span> toYYYYMM<span class="token punctuation">(</span>event_date<span class="token punctuation">)</span>                              <span class="token comment">-- 按月分区</span></span>
<span class="line">  <span class="token keyword">ORDER</span> <span class="token keyword">BY</span> <span class="token punctuation">(</span>tenant_id<span class="token punctuation">,</span> event_category<span class="token punctuation">,</span> event_date<span class="token punctuation">,</span> event_name<span class="token punctuation">,</span> event_ts<span class="token punctuation">)</span>  <span class="token comment">-- tenant_id 是首列</span></span>
<span class="line">  TTL event_date <span class="token operator">+</span> <span class="token keyword">INTERVAL</span> <span class="token number">180</span> <span class="token keyword">DAY</span></span>
<span class="line">  SETTINGS index_granularity <span class="token operator">=</span> <span class="token number">8192</span><span class="token punctuation">,</span> ttl_only_drop_parts <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>要点：</p><ul><li><strong><code>tenant_id</code> 是 ORDER BY 首列</strong>——租户的事件在排序的 part 里物理连续，租户级查询能跳过无关 granule。</li><li><strong>物化列</strong>：<code>event_date</code> 和 <code>event_ts</code> 由 <code>event_time</code> 推导，写入不重复存储，读取时计算。</li><li><strong>TTL + <code>ttl_only_drop_parts</code></strong>：过期按&quot;整 part 删除&quot;而非行级，效率高。</li><li><strong>跳数索引</strong>：bloom_filter（精确等值）、<code>ngrambf_v1</code>（XPath 子串搜索，热力图用）、<code>set</code>（极低基数）。</li><li><strong><code>LowCardinality(String)</code></strong>：对 <code>event_name</code> 这类枚举字段用字典编码，省存储加速扫描。</li></ul><h3 id="_3-2-doris-ddl-sql-doris-1-base-tables-sql" tabindex="-1"><a class="header-anchor" href="#_3-2-doris-ddl-sql-doris-1-base-tables-sql"><span>3.2 Doris DDL（<code>sql/doris/1_base_tables.sql</code>）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code><span class="line"><span class="token keyword">CREATE</span> <span class="token keyword">TABLE</span> <span class="token keyword">IF</span> <span class="token operator">NOT</span> <span class="token keyword">EXISTS</span> events_fact <span class="token punctuation">(</span></span>
<span class="line">    event_id <span class="token keyword">VARCHAR</span><span class="token punctuation">(</span><span class="token number">128</span><span class="token punctuation">)</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span><span class="token punctuation">,</span></span>
<span class="line">    tenant_id <span class="token keyword">INT</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span><span class="token punctuation">,</span></span>
<span class="line">    event_time DATETIMEV2<span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span></span>
<span class="line">    event_ts <span class="token keyword">BIGINT</span> GENERATED ALWAYS <span class="token keyword">AS</span> <span class="token punctuation">(</span>UNIX_TIMESTAMP<span class="token punctuation">(</span>event_time<span class="token punctuation">)</span><span class="token operator">*</span><span class="token number">1000</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment">-- 生成列</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span></span>
<span class="line">    context MAP<span class="token operator">&lt;</span>STRING<span class="token punctuation">,</span>STRING<span class="token operator">&gt;</span><span class="token punctuation">,</span></span>
<span class="line">    metrics MAP<span class="token operator">&lt;</span>STRING<span class="token punctuation">,</span><span class="token keyword">DOUBLE</span><span class="token operator">&gt;</span><span class="token punctuation">,</span></span>
<span class="line">    properties MAP<span class="token operator">&lt;</span>STRING<span class="token punctuation">,</span>STRING<span class="token operator">&gt;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token keyword">INDEX</span> idx_event_name <span class="token punctuation">(</span>event_name<span class="token punctuation">)</span> <span class="token keyword">USING</span> INVERTED<span class="token punctuation">,</span>    <span class="token comment">-- 倒排索引</span></span>
<span class="line">    <span class="token keyword">INDEX</span> idx_user_id   <span class="token punctuation">(</span>user_id<span class="token punctuation">)</span>   <span class="token keyword">USING</span> INVERTED<span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span>                                                   <span class="token comment">-- 12 个倒排索引</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">UNIQUE</span> <span class="token keyword">KEY</span><span class="token punctuation">(</span>event_id<span class="token punctuation">,</span> tenant_id<span class="token punctuation">,</span> event_time<span class="token punctuation">)</span>            <span class="token comment">-- 唯一键去重</span></span>
<span class="line">    <span class="token keyword">PARTITION</span> <span class="token keyword">BY</span> RANGE<span class="token punctuation">(</span>event_time<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token punctuation">)</span>                      <span class="token comment">-- 静态分区为空</span></span>
<span class="line">    <span class="token keyword">DISTRIBUTED</span> <span class="token keyword">BY</span> <span class="token keyword">HASH</span><span class="token punctuation">(</span>event_id<span class="token punctuation">,</span> tenant_id<span class="token punctuation">)</span> BUCKETS <span class="token number">16</span>    <span class="token comment">-- tenant_id 参与 hash，租户数据同桶聚集</span></span>
<span class="line">    PROPERTIES <span class="token punctuation">(</span></span>
<span class="line">        <span class="token string">&quot;dynamic_partition.enable&quot;</span> <span class="token operator">=</span> <span class="token string">&quot;true&quot;</span><span class="token punctuation">,</span>               <span class="token comment">-- 动态分区</span></span>
<span class="line">        <span class="token string">&quot;dynamic_partition.time_unit&quot;</span> <span class="token operator">=</span> <span class="token string">&quot;DAY&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;dynamic_partition.start&quot;</span> <span class="token operator">=</span> <span class="token string">&quot;-180&quot;</span><span class="token punctuation">,</span>                <span class="token comment">-- 保留 180 天</span></span>
<span class="line">        <span class="token string">&quot;dynamic_partition.end&quot;</span> <span class="token operator">=</span> <span class="token string">&quot;3&quot;</span><span class="token punctuation">,</span>                     <span class="token comment">-- 预创建未来 3 天</span></span>
<span class="line">        <span class="token string">&quot;enable_unique_key_merge_on_write&quot;</span> <span class="token operator">=</span> <span class="token string">&quot;true&quot;</span>        <span class="token comment">-- MoW 模式，按 event_id 去重</span></span>
<span class="line">    <span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>要点：</p><ul><li><strong>UNIQUE KEY + MoW</strong>：Doris 的唯一键模型 + 写时合并，按 <code>event_id</code> 去重（ClickHouse 用的是纯 append 的 MergeTree，靠 ReplacingMergeTree 在别处实现 upsert）。</li><li><strong>动态分区</strong>：<code>start=-180, end=3</code>，Doris 自动按天创建/裁剪分区，等价于 ClickHouse 的 TTL，但机制完全不同。</li><li><strong>倒排索引</strong>：Doris 的二级索引机制，跟 ClickHouse 的 bloom/skip 索引是两套东西。</li><li><strong><code>tenant_id</code> 参与 hash 分桶</strong>：跟 ClickHouse 把 <code>tenant_id</code> 放 ORDER BY 首列是同一个意图——<strong>让租户数据物理聚集</strong>，加速租户级扫描。</li></ul><h3 id="_3-3-双引擎对比一览" tabindex="-1"><a class="header-anchor" href="#_3-3-双引擎对比一览"><span>3.3 双引擎对比一览</span></a></h3><table><thead><tr><th>维度</th><th>ClickHouse</th><th>Doris</th></tr></thead><tbody><tr><td>引擎模型</td><td><code>MergeTree</code>（append-only）</td><td>UNIQUE KEY + merge-on-write（去重）</td></tr><tr><td>分区</td><td><code>toYYYYMM(event_date)</code> 按月</td><td>动态 RANGE 按 DAY，<code>start=-180</code></td></tr><tr><td>保留期</td><td><code>TTL + 180 DAY</code>，整 part 删</td><td><code>dynamic_partition.start = -180</code> 自动裁剪</td></tr><tr><td>排序/分桶键</td><td><code>ORDER BY (tenant_id, ...)</code></td><td><code>DISTRIBUTED BY HASH(event_id, tenant_id)</code></td></tr><tr><td>二级索引</td><td>8 个跳数索引（bloom/ngram/set）</td><td>12 个倒排索引</td></tr><tr><td>派生时间列</td><td><code>MATERIALIZED toDate(event_time)</code></td><td><code>GENERATED ALWAYS AS (UNIX_TIMESTAMP(event_time)*1000)</code></td></tr><tr><td>低基数优化</td><td><code>LowCardinality(String)</code></td><td>无（纯 VARCHAR）</td></tr></tbody></table><p><strong>同一个业务意图（租户聚集 + 时间分区 + 二级索引 + 派生列），两个引擎用完全不同的机制实现。</strong> 这就是&quot;双引擎&quot;的代价——也是它的价值：用户可以根据自己的运维栈选熟悉的引擎。</p><h2 id="四、方言映射-分歧到底有多大" tabindex="-1"><a class="header-anchor" href="#四、方言映射-分歧到底有多大"><span>四、方言映射：分歧到底有多大？</span></a></h2><p>跑过 25 个模型后，我总结出 ClickHouse 和 Doris 的分歧<strong>集中在 6~7 个函数</strong>上。SQL 骨架完全一样，换这些函数就行：</p><table><thead><tr><th>用途</th><th>Doris</th><th>ClickHouse</th></tr></thead><tbody><tr><td>计数</td><td><code>COUNT(*)</code></td><td><code>count()</code></td></tr><tr><td>去重计数</td><td><code>COUNT(DISTINCT user_id)</code></td><td><code>count(DISTINCT user_id)</code></td></tr><tr><td>ms 时间戳 → 日期</td><td><code>FROM_UNIXTIME(event_ts/1000, &#39;%Y-%m-%d&#39;)</code></td><td><code>toDate(event_ts / 1000)</code></td></tr><tr><td>路径拼接</td><td><code>GROUP_CONCAT(event_name SEPARATOR &#39; → &#39;)</code></td><td><code>arrayStringConcat(groupArray(event_name), &#39; → &#39;)</code></td></tr><tr><td>条件计数</td><td><code>SUM(CASE WHEN ... )</code></td><td><code>countIf(...)</code></td></tr><tr><td>Map 字段访问</td><td>列名直接取</td><td><code>context[&#39;stars&#39;]</code>、<code>metrics[&#39;score&#39;]</code></td></tr><tr><td>金额转换</td><td><code>CAST(amount AS DOUBLE)</code>、<code>ROUND(SUM(...),2)</code></td><td><code>toFloat64OrZero(toString(amount))</code></td></tr></tbody></table><p>驱动 API 也不同（这是更麻烦的部分）：</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token comment">// Doris（sqlx 风格）</span></span>
<span class="line">r<span class="token punctuation">.</span>db<span class="token punctuation">.</span><span class="token function">GetContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token operator">&amp;</span>cnt<span class="token punctuation">,</span> q<span class="token operator">+</span><span class="token string">&quot; LIMIT 1&quot;</span><span class="token punctuation">,</span> args<span class="token operator">...</span><span class="token punctuation">)</span>      <span class="token comment">// 标量</span></span>
<span class="line">r<span class="token punctuation">.</span>db<span class="token punctuation">.</span><span class="token function">SelectContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token operator">&amp;</span>rows<span class="token punctuation">,</span> q<span class="token punctuation">,</span> args<span class="token operator">...</span><span class="token punctuation">)</span>             <span class="token comment">// 切片</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// ClickHouse（clickhouse-go 风格）</span></span>
<span class="line">r<span class="token punctuation">.</span>db<span class="token punctuation">.</span><span class="token function">QueryRow</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token operator">&amp;</span>cnt<span class="token punctuation">,</span> q<span class="token punctuation">,</span> args<span class="token operator">...</span><span class="token punctuation">)</span>                   <span class="token comment">// 标量</span></span>
<span class="line">r<span class="token punctuation">.</span>db<span class="token punctuation">.</span><span class="token function">Select</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token operator">&amp;</span>rows<span class="token punctuation">,</span> q<span class="token punctuation">,</span> args<span class="token operator">...</span><span class="token punctuation">)</span>                    <span class="token comment">// 切片</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>struct tag 也得双份：Doris 用 <code>db:&quot;...&quot;</code>，ClickHouse 用 <code>ch:&quot;...&quot;</code>（部分字段 <code>ch:&quot;-&quot;</code> 排除物化列）。</p><p><strong>结论：维护成本是可控的。</strong> 一旦你接受了&quot;两份 repo 文件&quot;，每个新模型的增量工作就是：写一份 Doris SQL → 改 6~7 个函数和驱动调用 → 得到 ClickHouse 版本。骨架可复用，分歧点局部化。</p><h2 id="五、四个有技术含量的模型" tabindex="-1"><a class="header-anchor" href="#五、四个有技术含量的模型"><span>五、四个有技术含量的模型</span></a></h2><p>下面挑四个最能体现&quot;SQL 巧思&quot;的模型，把真实 SQL 贴出来。</p><h3 id="_5-1-归因分析-attribution-cte-窗口函数的教科书" tabindex="-1"><a class="header-anchor" href="#_5-1-归因分析-attribution-cte-窗口函数的教科书"><span>5.1 归因分析（Attribution）：CTE + 窗口函数的教科书</span></a></h3><p>归因要解决：&quot;用户最终转化了，但中间是哪个渠道/来源把他带来的？&quot; 经典的 first-touch / last-touch 模型。</p><p>这个实现用了<strong>两个 CTE + ROW_NUMBER 窗口函数</strong>，干净到可以写进教材（<code>doris/analytics_repo.go</code>）：</p><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code><span class="line"><span class="token keyword">WITH</span> converters <span class="token keyword">AS</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token comment">-- 先圈出&quot;在时间窗内完成转化事件&quot;的所有用户</span></span>
<span class="line">    <span class="token keyword">SELECT</span> <span class="token keyword">DISTINCT</span> user_id <span class="token keyword">FROM</span> events_fact</span>
<span class="line">    <span class="token keyword">WHERE</span> tenant_id <span class="token operator">=</span> ? <span class="token operator">AND</span> event_name <span class="token operator">=</span> ? <span class="token operator">AND</span> event_time <span class="token operator">&gt;=</span> ? <span class="token operator">AND</span> event_time <span class="token operator">&lt;</span> ?</span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">touchpoint <span class="token keyword">AS</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token comment">-- 回到这些转化用户的&quot;所有&quot;事件，按时间排序打行号</span></span>
<span class="line">    <span class="token keyword">SELECT</span> e<span class="token punctuation">.</span>user_id<span class="token punctuation">,</span> e<span class="token punctuation">.</span>channel <span class="token keyword">AS</span> dim_val<span class="token punctuation">,</span></span>
<span class="line">           ROW_NUMBER<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">OVER</span> <span class="token punctuation">(</span><span class="token keyword">PARTITION</span> <span class="token keyword">BY</span> e<span class="token punctuation">.</span>user_id <span class="token keyword">ORDER</span> <span class="token keyword">BY</span> e<span class="token punctuation">.</span>event_time <span class="token keyword">DESC</span><span class="token punctuation">)</span> <span class="token keyword">AS</span> rn</span>
<span class="line">    <span class="token keyword">FROM</span> events_fact e</span>
<span class="line">    <span class="token keyword">JOIN</span> converters c <span class="token keyword">ON</span> c<span class="token punctuation">.</span>user_id <span class="token operator">=</span> e<span class="token punctuation">.</span>user_id</span>
<span class="line">    <span class="token keyword">WHERE</span> e<span class="token punctuation">.</span>tenant_id <span class="token operator">=</span> ? <span class="token operator">AND</span> e<span class="token punctuation">.</span>event_time <span class="token operator">&gt;=</span> ? <span class="token operator">AND</span> e<span class="token punctuation">.</span>event_time <span class="token operator">&lt;</span> ?</span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">-- rn=1 即每个用户&quot;最后一次&quot;（last-touch）或&quot;第一次&quot;（first-touch）触点</span></span>
<span class="line"><span class="token keyword">SELECT</span> dim_val<span class="token punctuation">,</span> <span class="token function">COUNT</span><span class="token punctuation">(</span><span class="token keyword">DISTINCT</span> user_id<span class="token punctuation">)</span> <span class="token keyword">AS</span> converter_uv</span>
<span class="line"><span class="token keyword">FROM</span> touchpoint</span>
<span class="line"><span class="token keyword">WHERE</span> rn <span class="token operator">=</span> <span class="token number">1</span> <span class="token operator">AND</span> dim_val <span class="token operator">IS</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span> <span class="token operator">AND</span> dim_val <span class="token operator">&lt;&gt;</span> <span class="token string">&#39;&#39;</span></span>
<span class="line"><span class="token keyword">GROUP</span> <span class="token keyword">BY</span> dim_val</span>
<span class="line"><span class="token keyword">ORDER</span> <span class="token keyword">BY</span> converter_uv <span class="token keyword">DESC</span></span>
<span class="line"><span class="token keyword">LIMIT</span> <span class="token number">20</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>精妙之处：</p><ul><li><strong><code>ORDER BY e.event_time DESC</code> 还是 <code>ASC</code> 决定 last 还是 first touch。</strong> 这一点用 <code>fmt.Sprintf</code> 在 Go 层切换，逻辑零改动。</li><li><strong><code>rn = 1</code> 把每个用户折叠成一个触点</strong>，避免重复计算。</li><li><strong>全程用 <code>ROW_NUMBER</code>，不依赖任何厂商专有函数</strong>——所以 Doris 和 ClickHouse 都能跑。</li></ul><p>这是最优雅的一个模型。</p><h3 id="_5-2-ltv-case-阶梯分桶-go-侧累积" tabindex="-1"><a class="header-anchor" href="#_5-2-ltv-case-阶梯分桶-go-侧累积"><span>5.2 LTV：CASE 阶梯分桶 + Go 侧累积</span></a></h3><p>LTV（生命周期价值）要算：&quot;某批同期群用户，在第 0/1/3/7/14/30/60/90 天，平均每人累计贡献了多少收入？&quot; 这是一个<strong>单调递增的累积曲线</strong>。</p><p>实现分两步（<code>doris/analytics_repo.go</code>）：</p><p><strong>第一步：固定观测阶梯</strong></p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line">maxDays <span class="token operator">:=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">uint32</span><span class="token punctuation">{</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">7</span><span class="token punctuation">,</span> <span class="token number">14</span><span class="token punctuation">,</span> <span class="token number">30</span><span class="token punctuation">,</span> <span class="token number">60</span><span class="token punctuation">,</span> <span class="token number">90</span><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>第二步：用 CASE WHEN 把付费事件按&quot;距注册天数&quot;分桶</strong></p><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code><span class="line"><span class="token keyword">SELECT</span> u<span class="token punctuation">.</span>register_channel <span class="token keyword">AS</span> label<span class="token punctuation">,</span></span>
<span class="line">  <span class="token keyword">CASE</span></span>
<span class="line">    <span class="token keyword">WHEN</span> DATEDIFF<span class="token punctuation">(</span>e<span class="token punctuation">.</span>event_time<span class="token punctuation">,</span> u<span class="token punctuation">.</span>register_time<span class="token punctuation">)</span> <span class="token operator">&lt;=</span> <span class="token number">0</span>  <span class="token keyword">THEN</span> <span class="token number">0</span></span>
<span class="line">    <span class="token keyword">WHEN</span> DATEDIFF<span class="token punctuation">(</span>e<span class="token punctuation">.</span>event_time<span class="token punctuation">,</span> u<span class="token punctuation">.</span>register_time<span class="token punctuation">)</span> <span class="token operator">&lt;=</span> <span class="token number">1</span>  <span class="token keyword">THEN</span> <span class="token number">1</span></span>
<span class="line">    <span class="token keyword">WHEN</span> DATEDIFF<span class="token punctuation">(</span>e<span class="token punctuation">.</span>event_time<span class="token punctuation">,</span> u<span class="token punctuation">.</span>register_time<span class="token punctuation">)</span> <span class="token operator">&lt;=</span> <span class="token number">3</span>  <span class="token keyword">THEN</span> <span class="token number">3</span></span>
<span class="line">    <span class="token keyword">WHEN</span> DATEDIFF<span class="token punctuation">(</span>e<span class="token punctuation">.</span>event_time<span class="token punctuation">,</span> u<span class="token punctuation">.</span>register_time<span class="token punctuation">)</span> <span class="token operator">&lt;=</span> <span class="token number">7</span>  <span class="token keyword">THEN</span> <span class="token number">7</span></span>
<span class="line">    <span class="token keyword">WHEN</span> DATEDIFF<span class="token punctuation">(</span>e<span class="token punctuation">.</span>event_time<span class="token punctuation">,</span> u<span class="token punctuation">.</span>register_time<span class="token punctuation">)</span> <span class="token operator">&lt;=</span> <span class="token number">14</span> <span class="token keyword">THEN</span> <span class="token number">14</span></span>
<span class="line">    <span class="token keyword">WHEN</span> DATEDIFF<span class="token punctuation">(</span>e<span class="token punctuation">.</span>event_time<span class="token punctuation">,</span> u<span class="token punctuation">.</span>register_time<span class="token punctuation">)</span> <span class="token operator">&lt;=</span> <span class="token number">30</span> <span class="token keyword">THEN</span> <span class="token number">30</span></span>
<span class="line">    <span class="token keyword">WHEN</span> DATEDIFF<span class="token punctuation">(</span>e<span class="token punctuation">.</span>event_time<span class="token punctuation">,</span> u<span class="token punctuation">.</span>register_time<span class="token punctuation">)</span> <span class="token operator">&lt;=</span> <span class="token number">60</span> <span class="token keyword">THEN</span> <span class="token number">60</span></span>
<span class="line">    <span class="token keyword">ELSE</span> <span class="token number">90</span></span>
<span class="line">  <span class="token keyword">END</span> <span class="token keyword">AS</span> day_n<span class="token punctuation">,</span></span>
<span class="line">  <span class="token function">ROUND</span><span class="token punctuation">(</span><span class="token function">SUM</span><span class="token punctuation">(</span>e<span class="token punctuation">.</span>amount<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span> <span class="token keyword">AS</span> total_amount</span>
<span class="line"><span class="token keyword">FROM</span> events_fact e</span>
<span class="line"><span class="token keyword">JOIN</span> users_dim u <span class="token keyword">ON</span> u<span class="token punctuation">.</span>tenant_id <span class="token operator">=</span> e<span class="token punctuation">.</span>tenant_id <span class="token operator">AND</span> u<span class="token punctuation">.</span>user_id <span class="token operator">=</span> e<span class="token punctuation">.</span>user_id</span>
<span class="line"><span class="token keyword">WHERE</span> u<span class="token punctuation">.</span>tenant_id <span class="token operator">=</span> ? <span class="token operator">AND</span> u<span class="token punctuation">.</span>register_time <span class="token operator">&gt;=</span> ? <span class="token operator">AND</span> u<span class="token punctuation">.</span>register_time <span class="token operator">&lt;</span> ?</span>
<span class="line">  <span class="token operator">AND</span> e<span class="token punctuation">.</span>amount <span class="token operator">&gt;</span> <span class="token number">0</span> <span class="token operator">AND</span> e<span class="token punctuation">.</span>user_id <span class="token operator">&gt;</span> <span class="token number">0</span></span>
<span class="line"><span class="token keyword">GROUP</span> <span class="token keyword">BY</span> label<span class="token punctuation">,</span> day_n</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>第三步：Go 侧走阶梯累加</strong></p><p>SQL 返回的是每个桶的总额；Go 按天 <code>0→1→3→...→90</code> 升序走，累加：<code>cumulative += bucketSum[label][dayN]</code>，再 <code>ltv = cumulative / cohortSize</code>。最终得到 LTV(0)、LTV(1)、LTV(3)…… 一条单调递增的&quot;累计每获客收入&quot;曲线。</p><p>技巧点评：</p><ul><li><strong>分桶用 <code>DATEDIFF(event_time, register_time)</code>（事件时间减注册时间的天数差）+ CASE 阶梯</strong>，而不是用 SQL 窗口函数 SUM OVER——因为分桶点是不规则的 <code>{0,1,3,7,14,30,60,90}</code>，CASE 比窗口灵活。</li><li><strong>累积曲线故意放在 Go 里</strong>，不在 SQL 里做——这样同一个 SQL 结果可以同时算&quot;累计 LTV&quot;和&quot;分桶 LTV&quot;，复用性好。</li><li><strong>可选维度</strong>：<code>dimension == &quot;channel&quot;</code> 时 SELECT 改成 <code>u.register_channel AS label</code>，就能看每个渠道的 LTV 曲线。</li></ul><h3 id="_5-3-路径桑基-pathsankey-三层嵌套-group-concat" tabindex="-1"><a class="header-anchor" href="#_5-3-路径桑基-pathsankey-三层嵌套-group-concat"><span>5.3 路径桑基（PathSankey）：三层嵌套 + GROUP_CONCAT</span></a></h3><p>要把&quot;用户在每个会话里的事件序列&quot;聚合成 TOP N 路径，喂给桑基图。实现是三层嵌套（<code>doris/analytics_repo.go</code>）：</p><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code><span class="line"><span class="token keyword">SELECT</span> event_sequence<span class="token punctuation">,</span> <span class="token function">COUNT</span><span class="token punctuation">(</span><span class="token operator">*</span><span class="token punctuation">)</span> <span class="token keyword">AS</span> support_count<span class="token punctuation">,</span></span>
<span class="line">       <span class="token function">COUNT</span><span class="token punctuation">(</span><span class="token keyword">DISTINCT</span> user_id<span class="token punctuation">)</span> <span class="token keyword">AS</span> unique_users<span class="token punctuation">,</span> <span class="token number">0</span> <span class="token keyword">AS</span> conversion_rate</span>
<span class="line"><span class="token keyword">FROM</span> <span class="token punctuation">(</span></span>
<span class="line">  <span class="token comment">-- 第三层：每个(用户,会话)拼成 &quot;事件A → 事件B → 事件C&quot; 字符串</span></span>
<span class="line">  <span class="token keyword">SELECT</span> user_id<span class="token punctuation">,</span> session_id<span class="token punctuation">,</span></span>
<span class="line">         GROUP_CONCAT<span class="token punctuation">(</span>event_name SEPARATOR <span class="token string">&#39; → &#39;</span><span class="token punctuation">)</span> <span class="token keyword">AS</span> event_sequence</span>
<span class="line">  <span class="token keyword">FROM</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token comment">-- 第二层：保证时间顺序</span></span>
<span class="line">    <span class="token keyword">SELECT</span> user_id<span class="token punctuation">,</span> session_id<span class="token punctuation">,</span> event_name<span class="token punctuation">,</span> event_time</span>
<span class="line">    <span class="token keyword">FROM</span> events_fact</span>
<span class="line">    <span class="token keyword">WHERE</span> tenant_id <span class="token operator">=</span> ? <span class="token operator">AND</span> event_time <span class="token operator">&gt;=</span> ? <span class="token operator">AND</span> event_time <span class="token operator">&lt;</span> ?</span>
<span class="line">      <span class="token operator">AND</span> session_id <span class="token operator">!=</span> <span class="token string">&#39;&#39;</span> <span class="token operator">AND</span> user_id <span class="token operator">&gt;</span> <span class="token number">0</span></span>
<span class="line">    <span class="token keyword">ORDER</span> <span class="token keyword">BY</span> user_id<span class="token punctuation">,</span> session_id<span class="token punctuation">,</span> event_time</span>
<span class="line">  <span class="token punctuation">)</span> ordered</span>
<span class="line">  <span class="token keyword">GROUP</span> <span class="token keyword">BY</span> user_id<span class="token punctuation">,</span> session_id</span>
<span class="line"><span class="token punctuation">)</span> paths</span>
<span class="line"><span class="token keyword">WHERE</span> event_sequence <span class="token operator">IS</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span> <span class="token operator">AND</span> event_sequence <span class="token operator">!=</span> <span class="token string">&#39;&#39;</span></span>
<span class="line"><span class="token keyword">GROUP</span> <span class="token keyword">BY</span> event_sequence</span>
<span class="line"><span class="token keyword">ORDER</span> <span class="token keyword">BY</span> support_count <span class="token keyword">DESC</span></span>
<span class="line"><span class="token keyword">LIMIT</span> <span class="token number">20</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>ClickHouse 版只换一个函数：</p><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code><span class="line"><span class="token comment">-- Doris:  GROUP_CONCAT(event_name SEPARATOR &#39; → &#39;)</span></span>
<span class="line"><span class="token comment">-- CH:     arrayStringConcat(groupArray(event_name), &#39; → &#39;)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>关键赌注：<strong>内层 <code>ORDER BY</code> 在聚合时是否被保留？</strong> Doris 在 <code>GROUP_CONCAT</code> 里通常保留内层顺序；ClickHouse 的 <code>groupArray</code> 也倾向于保留插入顺序（虽然不是契约保证）。这是这个查询能 work 的隐含前提。<code>topN</code> 被夹在 <code>[1, 200]</code>，默认 20。</p><blockquote><p>注：<code>conversion_rate</code> 这里硬编码成 <code>0</code>——没有 join 目标事件。这是个已知的小局限，源码里也这么写着。</p></blockquote><h3 id="_5-4-漏斗-funnel-诚实的-非严格-实现" tabindex="-1"><a class="header-anchor" href="#_5-4-漏斗-funnel-诚实的-非严格-实现"><span>5.4 漏斗（Funnel）：诚实的&quot;非严格&quot;实现</span></a></h3><p>漏斗分析要算：&quot;从步骤 1 到步骤 N，每一步的转化率是多少？&quot;</p><p>这里有个<strong>必须说清楚的取舍</strong>。源码注释明说（<code>doris/analytics_repo.go:105-106</code>）：</p><blockquote><p>统计口径：每个步骤 = 在时间范围内完成该事件的去重用户数（不做严格顺序穿透，这是 Doris 上的近实时实现；严格漏斗需事件级顺序匹配，留作后续优化）。</p></blockquote><p>也就是说，<strong>它不是真正的&quot;有序漏斗&quot;</strong>。它做的是：每个步骤独立查一次&quot;时间窗内做过该事件的去重用户数&quot;，然后在 Go 里做除法：</p><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code><span class="line"><span class="token comment">-- 每个步骤发一次（循环 N 次）</span></span>
<span class="line"><span class="token keyword">SELECT</span> <span class="token function">COUNT</span><span class="token punctuation">(</span><span class="token keyword">DISTINCT</span> user_id<span class="token punctuation">)</span> <span class="token keyword">AS</span> cnt <span class="token keyword">FROM</span> events_fact</span>
<span class="line"><span class="token keyword">WHERE</span> event_time <span class="token operator">&gt;=</span> ? <span class="token operator">AND</span> event_time <span class="token operator">&lt;</span> ? <span class="token operator">AND</span> event_name <span class="token operator">=</span> ?</span>
<span class="line"><span class="token punctuation">[</span><span class="token operator">AND</span> tenant_id <span class="token operator">=</span> ?<span class="token punctuation">]</span></span>
<span class="line"><span class="token keyword">LIMIT</span> <span class="token number">1</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Go 侧算转化率：</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token comment">// 步骤 i 的转化率 = 步骤 i 的人数 / 步骤 i-1 的人数</span></span>
<span class="line"><span class="token comment">// 步骤 i 的总体转化率 = 步骤 i 的人数 / 步骤 0 的人数</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>为什么不严格？</strong> 因为严格有序漏斗需要&quot;同一个用户在时间上依次触发 step1→step2→step3&quot;。ClickHouse 有 <code>windowFunnel()</code> 函数能干这事，Doris 没有等价物。为了双引擎行为一致，作者选择了<strong>两个引擎都能跑的简化口径</strong>，代价是&quot;漏斗&quot;退化为&quot;各步骤独立去重用户数 + 算术&quot;。</p><p>这是一个<strong>用精度换双引擎一致性 + 近实时性能</strong>的典型取舍。源码诚实标注了，这点值得尊敬。如果你需要严格漏斗，要么只用 ClickHouse 走 <code>windowFunnel</code>，要么自己加一层。</p><h2 id="六、维度白名单-防-sql-注入的正解" tabindex="-1"><a class="header-anchor" href="#六、维度白名单-防-sql-注入的正解"><span>六、维度白名单：防 SQL 注入的正解</span></a></h2><p>分析查询里维度字段（dimension）是用户传的字符串，比如 <code>&quot;channel&quot;</code> / <code>&quot;platform&quot;</code>。这里有个经典安全问题：<strong>SQL 标识符不能参数化</strong>（<code>SELECT ? FROM ...</code> 不行），但又不能直接拼用户输入。怎么破？</p><p>项目用了一个两层白名单（<code>doris/analytics_repo.go:2255-2272</code>、<code>clickhouse/analytics_helpers.go:32-48</code>）：</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">func</span> <span class="token function">allowedDimension</span><span class="token punctuation">(</span>dim <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token builtin">string</span><span class="token punctuation">,</span> <span class="token builtin">bool</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    m <span class="token operator">:=</span> <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span></span>
<span class="line">        <span class="token string">&quot;platform&quot;</span><span class="token punctuation">:</span>       <span class="token string">&quot;platform&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;channel&quot;</span><span class="token punctuation">:</span>        <span class="token string">&quot;channel&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;country&quot;</span><span class="token punctuation">:</span>        <span class="token string">&quot;country&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;app_version&quot;</span><span class="token punctuation">:</span>    <span class="token string">&quot;app_version&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;event_name&quot;</span><span class="token punctuation">:</span>     <span class="token string">&quot;event_name&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;event_category&quot;</span><span class="token punctuation">:</span> <span class="token string">&quot;event_category&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;os&quot;</span><span class="token punctuation">:</span>             <span class="token string">&quot;os&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;network&quot;</span><span class="token punctuation">:</span>        <span class="token string">&quot;network&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;user_level&quot;</span><span class="token punctuation">:</span>     <span class="token string">&quot;user_level&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;vip_level&quot;</span><span class="token punctuation">:</span>      <span class="token string">&quot;vip_level&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    v<span class="token punctuation">,</span> ok <span class="token operator">:=</span> m<span class="token punctuation">[</span>dim<span class="token punctuation">]</span></span>
<span class="line">    <span class="token keyword">return</span> v<span class="token punctuation">,</span> ok</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>用法：</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line">col<span class="token punctuation">,</span> ok <span class="token operator">:=</span> <span class="token function">allowedDimension</span><span class="token punctuation">(</span>req<span class="token punctuation">.</span><span class="token function">GetDimension</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token operator">!</span>ok <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> ubaV1<span class="token punctuation">.</span><span class="token function">ErrorBadRequest</span><span class="token punctuation">(</span>fmt<span class="token punctuation">.</span><span class="token function">Sprintf</span><span class="token punctuation">(</span><span class="token string">&quot;unsupported dimension: %s&quot;</span><span class="token punctuation">,</span> req<span class="token punctuation">.</span><span class="token function">GetDimension</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token comment">// 返回的 col 来自 map 的 value（服务端控制的字面量），不是用户输入</span></span>
<span class="line">q <span class="token operator">:=</span> fmt<span class="token punctuation">.</span><span class="token function">Sprintf</span><span class="token punctuation">(</span><span class="token string">&quot;SELECT %s AS label, %s AS value FROM events_fact %s WHERE ...&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    col<span class="token punctuation">,</span> metricExpr<span class="token punctuation">,</span> joinClause<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>机制要点：</p><ol><li><strong>白名单 map</strong>：只有这 10 个已知安全的列名能通过；返回值是 <strong>map 的 value（服务端字面量）</strong>，不是原始用户输入。未知维度直接 <code>400 Bad Request</code>。</li><li><strong>metric 也有白名单</strong>（switch）：<code>COUNT</code> / <code>UNIQUE_USER</code> / <code>SUM_AMOUNT</code>，从不拼接用户文本。</li><li><strong>identifier 拼接 + value 绑定</strong>：白名单解析后的列名确实用 <code>fmt.Sprintf</code> 拼进 SQL（因为标识符不能参数化），但因为它来自固定 map，值保证安全；用户传入的<strong>数值</strong>一律用 <code>?</code> 绑定。</li><li><strong><code>user_level</code> / <code>vip_level</code> 触发 JOIN</strong>：这两个维度在 <code>users_dim</code> 表而不是 <code>events_fact</code>，代码会自动构造 <code>JOIN users_dim u ON ...</code> 并给列名加 <code>u.</code> 前缀。</li></ol><p>这是<strong>标准且正确的防注入模式</strong>：标识符用白名单解析后拼接，值用参数绑定。每个分析方法的租户条件 <code>tenant_id = ?</code> 也都走绑定，从不字符串拼接。</p><blockquote><p>一个小细节：<code>Attribution</code> 没走 <code>allowedDimension</code>，而是自己写了 <code>if d == &quot;referer&quot; { dim = &quot;referer&quot; } else { channel }</code> 的硬编码分支——更简单，但用了不同的 guard 风格。代码里这种&quot;一致性瑕疵&quot;在真实项目里很常见。</p></blockquote><h2 id="七、25-个模型的全景" tabindex="-1"><a class="header-anchor" href="#七、25-个模型的全景"><span>七、25 个模型的全景</span></a></h2><p>把所有方法列出来感受下规模（都在 <code>analytics_repo.go</code>，Doris 版 2293 行，ClickHouse 版镜像）：</p><p><strong>通用行为分析（10）</strong>：EventTrend、Funnel、Retention、GroupBy、ActiveUsers、Attribution、Distribution、BehaviorSequence、Segmentation、Click</p><p><strong>用户深度洞察（9）</strong>：Lifecycle、Churn、Interval、Matrix、Revenue、SessionAnalysis、Anomaly、NewVsOld、PathSankey</p><p><strong>游戏专项（6）</strong>：LevelAnalysis、WhaleTier、LTV、ServerRetention、OnlineStats、Economy</p><p>每个都是 <code>func (r *AnalyticsRepo) Xxx(ctx, req) (resp, error)</code>，Doris/CH 各一份。最有&quot;算法味&quot;的几个：</p><ul><li><strong>Anomaly（异常检测）</strong>：事件环比涨跌 + 7 日基线预警，发现埋点丢失/故障。</li><li><strong>WhaleTier（付费分层）</strong>：把付费用户按金额分大/中/小课长，验证二八定律。</li><li><strong>Economy（经济系统）</strong>：代币产出/消耗平衡监控，防通胀和刷币。</li><li><strong>LevelAnalysis（关卡分析）</strong>：通过率/卡关率/满星率，游戏数值平衡。</li></ul><p>这些模型的 SQL 风格大同小异：<strong>时间窗 + tenant 条件 + GROUP BY 维度 + 聚合函数</strong>，区别在聚合的具体表达（CASE 分桶 / 窗口函数 / DATEDIFF）。</p><h2 id="八、小结-双引擎值不值得" tabindex="-1"><a class="header-anchor" href="#八、小结-双引擎值不值得"><span>八、小结：双引擎值不值得？</span></a></h2><p>回到开头的赌注。维护两份 OLAP repo、两份 DDL、两套方言映射，<strong>值得吗</strong>？</p><p>我的看法是——<strong>对开源项目值得，对单一公司项目未必</strong>：</p><ul><li><strong>开源项目</strong>：用户运维栈各异，有人吃 Doris（兼容 MySQL 协议、运维熟），有人吃 ClickHouse（极致 scan 性能）。给选择权 = 拓宽用户面。维护成本可控（如前述，分歧只在 6~7 个函数）。</li><li><strong>单一公司</strong>：除非真有切换引擎的需求，否则选一个深挖更划算。双引擎的代码分支会渗入每个 service（<code>if data.UseClickHouse</code>），增加心智负担。</li></ul><p>GoWind UBA 选择双引擎，更多是<strong>给社区一个选择</strong>的姿态。而它把双引擎分歧控制得足够局部（repo 层 + 驱动 API + 6~7 个函数），是一个值得学习的工程克制。</p><hr><p><em>本文 SQL 全部出自 <a href="https://github.com/tx7do/go-wind-uba" target="_blank" rel="noopener noreferrer">go-wind-uba</a> 仓库 <code>backend/app/core/service/internal/data/{doris,clickhouse}/analytics_repo.go</code>，DDL 出自 <code>backend/sql/{doris,clickhouse}/</code>。</em></p>`,99)])])}const i=s(p,[["render",o]]),u=JSON.parse('{"path":"/posts/go-wind-uba-olap-sql-deep-dive.html","title":"Go Wind UBA 拆解系列 - OLAP 与 SQL 硬核：25 个分析模型怎么落地","lang":"zh-CN","frontmatter":{"date":"2026-07-02T00:00:00.000Z","category":["GoWind风行"],"tag":["UBA","大数据分析","Golang","GoWind"],"sticky":10},"headers":[{"level":2,"title":"一、为什么是双引擎？","slug":"一、为什么是双引擎","link":"#一、为什么是双引擎","children":[]},{"level":2,"title":"二、双引擎切换：一个编译期常量","slug":"二、双引擎切换-一个编译期常量","link":"#二、双引擎切换-一个编译期常量","children":[]},{"level":2,"title":"三、Schema：同一张表，两种 DDL","slug":"三、schema-同一张表-两种-ddl","link":"#三、schema-同一张表-两种-ddl","children":[{"level":3,"title":"3.1 ClickHouse DDL（sql/clickhouse/1_base_tables.sql）","slug":"_3-1-clickhouse-ddl-sql-clickhouse-1-base-tables-sql","link":"#_3-1-clickhouse-ddl-sql-clickhouse-1-base-tables-sql","children":[]},{"level":3,"title":"3.2 Doris DDL（sql/doris/1_base_tables.sql）","slug":"_3-2-doris-ddl-sql-doris-1-base-tables-sql","link":"#_3-2-doris-ddl-sql-doris-1-base-tables-sql","children":[]},{"level":3,"title":"3.3 双引擎对比一览","slug":"_3-3-双引擎对比一览","link":"#_3-3-双引擎对比一览","children":[]}]},{"level":2,"title":"四、方言映射：分歧到底有多大？","slug":"四、方言映射-分歧到底有多大","link":"#四、方言映射-分歧到底有多大","children":[]},{"level":2,"title":"五、四个有技术含量的模型","slug":"五、四个有技术含量的模型","link":"#五、四个有技术含量的模型","children":[{"level":3,"title":"5.1 归因分析（Attribution）：CTE + 窗口函数的教科书","slug":"_5-1-归因分析-attribution-cte-窗口函数的教科书","link":"#_5-1-归因分析-attribution-cte-窗口函数的教科书","children":[]},{"level":3,"title":"5.2 LTV：CASE 阶梯分桶 + Go 侧累积","slug":"_5-2-ltv-case-阶梯分桶-go-侧累积","link":"#_5-2-ltv-case-阶梯分桶-go-侧累积","children":[]},{"level":3,"title":"5.3 路径桑基（PathSankey）：三层嵌套 + GROUP_CONCAT","slug":"_5-3-路径桑基-pathsankey-三层嵌套-group-concat","link":"#_5-3-路径桑基-pathsankey-三层嵌套-group-concat","children":[]},{"level":3,"title":"5.4 漏斗（Funnel）：诚实的\\"非严格\\"实现","slug":"_5-4-漏斗-funnel-诚实的-非严格-实现","link":"#_5-4-漏斗-funnel-诚实的-非严格-实现","children":[]}]},{"level":2,"title":"六、维度白名单：防 SQL 注入的正解","slug":"六、维度白名单-防-sql-注入的正解","link":"#六、维度白名单-防-sql-注入的正解","children":[]},{"level":2,"title":"七、25 个模型的全景","slug":"七、25-个模型的全景","link":"#七、25-个模型的全景","children":[]},{"level":2,"title":"八、小结：双引擎值不值得？","slug":"八、小结-双引擎值不值得","link":"#八、小结-双引擎值不值得","children":[]}],"git":{"updatedTime":1782974568000,"contributors":[{"name":"Bobo","username":"Bobo","email":"yanglinbo@gmail.com","commits":1,"url":"https://github.com/Bobo"}],"changelog":[{"hash":"a177b25888e97f93db07390b7db7566c539a314e","time":1782974568000,"email":"yanglinbo@gmail.com","author":"Bobo","message":"feat: add posts."}]},"filePathRelative":"posts/go-wind-uba-olap-sql-deep-dive.md","excerpt":"\\n<blockquote>\\n<p>本文回答一个问题：<strong>25 个分析模型（漏斗 / 留存 / LTV / 归因 / 路径……）在 ClickHouse 和 Doris 上，到底是用什么 SQL 写出来的？双引擎又是怎么做到\\"一份业务模型，两份实现\\"的？</strong></p>\\n</blockquote>\\n<h2>一、为什么是双引擎？</h2>\\n<p>先说结论：GoWind UBA 支持 <strong>ClickHouse 和 Apache Doris 二选一</strong>，部署时按需选其一，运行时通过一个开关切换。这是一个很有意思的工程选择——为什么不让用户自己写 SQL，而要维护两份？</p>"}');export{i as comp,u as data};
